              this.$toast(data.msg)
              setTimeout(() => {
                Telegram.WebApp.close()
              }, 2000)
            }
          })
      }
    }
  },
  methods: {
    onConfirm(value) {
      this.form.needtypeTitle = value;
      this.needtype= value==="充值"?'1':(value==="流水"?'2':'0')
      if(value==='不限制'){
        this.showMonsInput=false
      }else{
        this.showMonsInput=true
      }
      this.typePicker = false;
    },
    cancelBlur() {
      // if (document.activeElement.tagName !== 'INPUT') {
      //   document.activeElement.blur()
      // }
      var inputs = document.getElementsByTagName('input')

      // 遍历input元素
      for (var i = 0; i < inputs.length; i++) {
        // 对每个input元素执行操作
        console.log(inputs[i])
        inputs[i].blur()
      }
    },
    changeParam(val1, val2) {
      this.currentPicIndex = val1
    },
    async saveRedpack() {
      //   let totalAmountSum // 总发包金额
      this.currentTypeIndex = this.actions.findIndex(item => item.type == this.currentType)
      const totalAmountSum = this.currentType === 1 ? this.actions[this.currentTypeIndex].nums * this.actions[this.currentTypeIndex].moneys : this.actions[this.currentTypeIndex].moneys
      if (this.actions[this.currentTypeIndex].nums > this.peopleNum) {
        this.$toast('红包数量应不大于群人数！')
        return false
      }
      if (this.remainingSum < totalAmountSum) {
        this.$dialog.confirm({
          title: '提示',
          message: '余额少于发包金额，是否跳转到充值页面？'
        })
          .then(() => {
            // this.$router.push({ path: '/telRecharge', query: { userid: this.userid, chatid: this.chatid }})
            this.toTelRecharge()
          })
          .catch(() => {
            // on cancel
          })

        return false
      }
      this.buttonText = '钱包提交中'
      this.disabled = true
      this.params = this.actions[this.currentTypeIndex]
      // this.params.gettype = String(this.tagColor)
      // this.params.suid = this.$route.query.suid
      this.params.suid = this.userid
      this.params.chatid = this.chatid
      this.params.needtype = this.needtype
      this.params.needmoney = this.form.needmoney
      if (this.params.type === '4') {
        this.params.type = this.titleColor === 0 ? '4' : '5'
      }
      if (this.params.type === '4') {
        this.params.remark = this.taskListZxh[this.currentPicIndex].title
      } else if (this.params.type === '5') {
        this.params.remark = this.taskListDmx[this.currentPicIndex].title
      } else {
        this.params.remark = this.params.remark ? this.params.remark : '恭喜发财，大吉大利'
      }
      // this.params.anonymous = this.params.anonymous === true ? '1' : '0'
      const anonymous1 = this.params.anonymous === true ? '1' : '0'
      this.saveClick = true
      this.buttonText = '钱包提交中'
      this.disabled = true
      if (this.currentType === 4) {
        debugger
        await this.$nextTick()
        html2canvas(document.getElementsByClassName('van-swipe-item')[this.currentPicIndex], {
          backgroundColor: null, // 解决生成会有白边的可能,但是没有遇到有白边,不知道有没有生效
          allowTaint: true, // 是否允许跨域图片(官方文档,代试验)
          useCORS: true,
          taintTest: true
        })
          .then(async(canvas) => {
            const dataURL = canvas.toDataURL('image/png')
            this.params.medialink = await this.uploadPic(dataURL)
            const paramString = '?type=' + this.params.type + '&nums=' + this.params.nums + '&tobotid=' + this.params.tobotid + '&moneys=' + this.params.moneys + '&medialink=' + this.params.medialink + '&remark=' + this.params.remark + '&anonymous=' + anonymous1 + '&gettype=' + this.params.gettype + '&suid=' + this.params.suid + '&chatid=' + this.params.chatid + '&needtype=' + this.params.needtype + '&needmoney=' + this.params.needmoney
            fetch(process.env.VUE_APP_BASE_API + '/yule/saveRedpack' + paramString, {
              method: 'POST'
            }).then(res => res.json())
              .then(data => {
                this.saveClick = false
                this.buttonText = '塞钱进钱包'
                this.disabled = false
                if (this.params.type == '5') {
                  this.params.type = '4'
                }
                if (data.status == '1') {
                  this.$toast('发送成功，请在TG群里查看红包发送情况!')
                  if (!this.$route.query.test) {
                    setTimeout(() => {
                      Telegram.WebApp.close()
                    }, 2000)
                  }
                } else {
                  this.$toast(data.msg)
                  if (!this.$route.query.test) {
                    setTimeout(() => {
                      Telegram.WebApp.close()
                    }, 2000)
                  }
                }
              })
          })
      } else {
        const paramString = '?type=' + this.params.type + '&nums=' + this.params.nums + '&tobotid=' + this.params.tobotid + '&moneys=' + this.params.moneys + '&medialink=' + this.params.medialink + '&remark=' + this.params.remark + '&anonymous=' + anonymous1 + '&gettype=' + this.params.gettype + '&suid=' + this.params.suid + '&chatid=' + this.params.chatid + '&needtype=' + this.params.needtype + '&needmoney=' + this.params.needmoney
        fetch(process.env.VUE_APP_BASE_API + '/yule/saveRedpack' + paramString, {
          method: 'POST'
        }).then(res => res.json())
          .then(data => {
            this.saveClick = false
            this.buttonText = '塞钱进钱包'
            this.disabled = false
            if (data.status == '1') {
              this.$toast('发送成功，请在TG群里查看红包发送情况!')
              if (!this.$route.query.test) {
                setTimeout(() => {
                  Telegram.WebApp.close()
                }, 2000)
              }
            } else {
              this.$toast(data.msg)
            }
          })
      }
    },
    btof(data, fileName) {
      const dataArr = data.split(',')
      const byteString = atob(dataArr[1])
      const options = {
        type: 'image/jpeg',
        endings: 'native'
      }
      const u8Arr = new Uint8Array(byteString.length)
      for (let i = 0; i < byteString.length; i++) {
        u8Arr[i] = byteString.charCodeAt(i)
      }
      return new File([u8Arr], fileName + '.jpg', options)
    },
    async uploadPic(base64) {
      const file = this.btof(base64, '合成.png')
      var formData = new FormData()
      formData.append('imgfile', file)
      return fetch(process.env.VUE_APP_BASE_API + '/yule/redpackimg', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(data => {
          return data.imgsrc
        })
    },
    async initData(data) {
      // 更新展示数据
      this.userid = data.userid
      this.chatid = data.chatid
      this.remainingSum = data.moneys
      this.peopleNum = data.membersize
      data.lastrecord.anonymous = data.lastrecord.anonymous === '1'
      data.lastrecord.type = String(data.lastrecord.type)
      if (data.lastrecord.type === '5') {
        data.lastrecord.type = '4'
        this.titleColor = 1
      }
      this.actions.forEach((item, index) => {
        if (item.type === data.lastrecord.type) {
          data.lastrecord.text = item.text
          //   data.lastrecord.tagColor = item.gettype
          // data.lastrecord.medialink = data.lastrecord.medialink ? data.lastrecord.medialink : item.medialink
          //   data.lastrecord.remark = data.lastrecord.remark ? data.lastrecord.remark : '恭喜发财，大吉大利'
          this.actions[index] = data.lastrecord
        }
      })
      if (this.$route.query.uname) {
        this.recipient = this.$route.query.uname
        this.currentType = 3
        this.currentTypeIndex = 2
        this.actions[this.currentTypeIndex].tobotid = this.$route.query.botid
      } else {
        this.currentType = Number(data.lastrecord.type)
        // this.currentTypeIndex = Number(data.lastrecord.type) - 1
        this.currentTypeIndex = this.actions.findIndex(item => item.type == this.currentType)
      }
      if (this.currentType !== 4) {
        if (data.lastrecord.medialink !== 'http://img.rr888.vip/img/yl-hbmrtb.png') {
          // this.uploader[1] = { url: data.lastrecord.medialink }
          this.uploader = [{ url: 'http://img.rr888.vip/img/yl-hbmrtb.png', deletable: false }, { url: data.lastrecord.medialink }]
          await this.$nextTick()
          this.clickPreview(this.uploader[1], data.lastrecord.medialink)
        } else {
          await this.$nextTick()
          this.clickPreview(this.uploader[0], data.lastrecord.medialink)
        }
      }
      this.form = this.actions[this.currentTypeIndex]
    },
    toTelRecharge() {
      const myJSON = JSON.stringify(this.actions[this.currentTypeIndex])
      this.$router.push({ path: '/telRecharge', query: { suid: this.userid, chatid: this.chatid, myJSON }})
    },
    clickPreview(file, url) {
      let ele
      if (file.deletable === false) {
        ele = document.getElementsByClassName('van-uploader__preview')[0]
        if (document.getElementsByClassName('van-uploader__preview')[1]) {
          document.getElementsByClassName('van-uploader__preview')[1].style.border = 'none'
        }
      } else {
        ele = document.getElementsByClassName('van-uploader__preview')[1]
        document.getElementsByClassName('van-uploader__preview')[0].style.border = 'none'
      }
      // const ele = document.getElementsByClassName('van-uploader__preview')[0]
      if (ele) {
        ele.style.border = '1px solid #07c160'
      }
      this.actions[this.currentTypeIndex].medialink = file.url || url
    //   this.params.medialink = file.url || url
    },
    goList() {
      const myJSON = JSON.stringify(this.actions[this.currentTypeIndex])
      this.$router.push({ path: '/peopleList', query: { userid: this.userid, chatid: this.chatid, myJSON }})
    },
    afterRead(file) {
      console.log(file)
      var formData = new FormData()
      formData.append('imgfile', file.file)
      fetch(process.env.VUE_APP_BASE_API + '/yule/redpackimg', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(async data => {
          this.uploader = [{ url: 'http://img.rr888.vip/img/yl-hbmrtb.png', deletable: false }, { url: data.imgsrc }]
          await this.$nextTick()
          this.clickPreview(file, data.imgsrc)
        })
    },
    async onSelect(action) {
      if (action.type == '5') {
        action.type = '4'
      }
      this.currentType = Number(action.type)
      this.currentTypeIndex = this.actions.findIndex(item => item.type == this.currentType)
      this.form = this.actions[this.currentTypeIndex]
      this.needtype = this.form.needtypeTitle==="充值"?'1':(this.form.needtypeTitle==="流水"?'2':'0')
      if (this.currentType !== 4) {
        await this.$nextTick()
        this.clickPreview(this.uploader[0])
      }
    },
    // onChange(){
    //   debugger
    //   this.needtype=''
    //   this.form.needtypeTitle='不限制'
    //   this.form.needmoney=''
    // },
    onChoose(id) {
      this.tagColor = id
      this.actions[this.currentTypeIndex].gettype = String(id)
    },
    onChoose1(id) {
      this.titleColor = id
      this.actions[this.currentTypeIndex].titleColor = id
    //   this.params.type = id === 0 ? '4' : '5'
    },
    onSubmit() {
    }
  }

}
</script>
